# Serpentine3D Labs plugin: editdimension
#
# A preview of a proposed Serpentine3D change (chisomobanzi/Serpentine3D#182).
# Put this file in ~/.serpentine3d/plugins/ and restart Serpentine3D.
# Commands:
#   editdimension  pick a box's edge, face or fillet and retype its size or radius
# Delete the file to remove them.
#
# Generated by tools/build.py from SlapBackers/Serpentine3D, branch editable-dimensions;
# do not edit by hand. Home: https://github.com/SlapBackers/serpentine3d-labs

"""The dimensions a filleted box was made with, read back from its shape.

Draw a box 40 x 30 x 20, fillet some edges at 3, and the solid forgets
both numbers: what is left is faces. They can be read back. The flat faces
come in three pairs, square to each other, and the distance across each
pair is a side; each fillet is a cylinder whose axis sits its radius in
from two of those faces, which says both the radius and the edge it
rounds. Rebuilt from those numbers, the solid must come out the same, or
the shape was something else and nothing is claimed about it.

Because the numbers come from the shape and not from a record of how it
was built, this works for a box drawn with `box`, filleted with
`filletedge` or the gumball, moved, turned, or imported from a STEP or
.3dm file. A changed number rebuilds the box and fillets the same edges
again, so a 3 mm fillet stays 3 mm when the box grows.
"""


from dataclasses import dataclass, field, replace

import numpy as np

from serpentine3d.core import occ

# how close two directions must be to count as one, and two lengths
_PARALLEL = 1 - 1e-7
_REL = 1e-7


class NotABox(Exception):
    """The shape is not a box with fillets on its edges."""


@dataclass(frozen=True)
class BoxModel:
    """A box and the fillets on its edges.

    `axes` are three unit vectors, right-handed; `origin` is the corner the
    box grows from and `size` its extent along each axis. An edge of the box
    is where two faces meet; a face is (axis, side), side 0 at the origin
    and 1 across, and an edge is the pair of its two faces, the lower axis
    first. `fillets` maps such an edge to its radius."""
    origin: tuple
    axes: tuple
    size: tuple
    fillets: dict = field(default_factory=dict)

    def resized(self, axis: int, value: float, grow: str = "both"):
        """The box `value` long along `axis`, its fillets unchanged. `grow`
        says which side moves: "end" (side 1), "start" (side 0) or
        "both" (the centre stays)."""
        delta = value - self.size[axis]
        shift = {"end": 0.0, "start": -delta, "both": -delta / 2}[grow]
        origin = np.asarray(self.origin) + shift * np.asarray(self.axes[axis])
        size = list(self.size)
        size[axis] = value
        return replace(self, origin=tuple(origin), size=tuple(size))

    def with_radius(self, edge, radius: float):
        fillets = dict(self.fillets)
        fillets[edge] = radius
        return replace(self, fillets=fillets)


# --- reading ----------------------------------------------------------------

def read(shape, tolerance: float = 1e-6) -> BoxModel:
    """The box and fillets a solid is, or NotABox."""
    from serpentine3d.core.geometry import faces_of, shape_kind
    if shape_kind(shape) != "solid":
        raise NotABox("it is not a solid")
    planes, cylinders = [], []
    for face in faces_of(shape):
        kind, data = _surface(face)
        if kind == "plane":
            planes.append(data)
        elif kind == "cylinder":
            cylinders.append(data)
    axes = _three_axes([n for n, _p in planes])
    scale = max(1.0, float(max(abs(c) for _n, p in planes for c in p)))
    eps = max(tolerance, scale * _REL) * 10
    lows, highs = [], []
    for axis in axes:
        along = [float(np.dot(p, axis)) for n, p in planes
                 if abs(float(np.dot(n, axis))) > _PARALLEL]
        if len(along) != 2:
            raise NotABox("its flat faces are not three pairs")
        lows.append(min(along))
        highs.append(max(along))
    size = tuple(h - lo for lo, h in zip(lows, highs))
    if min(size) <= eps:
        raise NotABox("it is flat")
    origin = sum(lo * a for lo, a in zip(lows, axes))
    model = BoxModel(tuple(float(c) for c in origin),
                     tuple(tuple(float(c) for c in a) for a in axes), size)
    fillets = {}
    for direction, point, radius in cylinders:
        edge = _edge_of_fillet(model, direction, point, radius, eps)
        if edge is None:
            raise NotABox("a curved face is not a fillet on one of its edges")
        if edge in fillets and abs(fillets[edge] - radius) > eps:
            raise NotABox("an edge has two different fillets")
        fillets[edge] = radius
    model = replace(model, fillets=fillets)
    _same_solid(shape, build(model), scale, eps)
    return model


def _surface(face):
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    from OCP.GeomAbs import GeomAbs_SurfaceType
    s = BRepAdaptor_Surface(face)
    kind = s.GetType()
    if kind == GeomAbs_SurfaceType.GeomAbs_Plane:
        ax = s.Plane().Axis()
        return "plane", (_vec(ax.Direction()), _vec(ax.Location()))
    if kind == GeomAbs_SurfaceType.GeomAbs_Cylinder:
        c = s.Cylinder()
        ax = c.Axis()
        return "cylinder", (_vec(ax.Direction()), _vec(ax.Location()),
                            float(c.Radius()))
    return "other", None


def _vec(v):
    return np.array([v.X(), v.Y(), v.Z()], float)


def _three_axes(normals):
    """Three square directions the flat faces face, right-handed."""
    axes = []
    for n in normals:
        if not any(abs(float(np.dot(n, a))) > _PARALLEL for a in axes):
            axes.append(n / np.linalg.norm(n))
    if len(axes) != 3:
        raise NotABox("its flat faces do not face three ways")
    for i in range(3):
        for j in range(i + 1, 3):
            if abs(float(np.dot(axes[i], axes[j]))) > 1e-7:
                raise NotABox("its sides are not square to each other")
    # the order that makes the axes run like x, y, z for a box drawn on
    # the world plane, so its sizes read in the order they were typed
    world = np.eye(3)
    order = sorted(range(3), key=lambda i: int(np.argmax(np.abs(
        axes[i] @ world.T))))
    u, v = axes[order[0]], axes[order[1]]
    u = u if u[int(np.argmax(np.abs(u)))] > 0 else -u
    v = v if v[int(np.argmax(np.abs(v)))] > 0 else -v
    return u, v, np.cross(u, v)


def _edge_of_fillet(model, direction, point, radius, eps):
    """The box edge a cylinder rounds: its axis runs along one box axis and
    sits `radius` in from a face on each of the other two."""
    along = [i for i in range(3)
             if abs(float(np.dot(direction, model.axes[i]))) > _PARALLEL]
    if len(along) != 1:
        return None
    a, b = (i for i in range(3) if i != along[0])
    local = point - np.asarray(model.origin)
    sides = []
    for axis in (a, b):
        t = float(np.dot(local, model.axes[axis]))
        if abs(t - radius) <= eps:
            sides.append(0)
        elif abs(t - (model.size[axis] - radius)) <= eps:
            sides.append(1)
        else:
            return None
    return (a, sides[0], b, sides[1])


def _same_solid(shape, rebuilt, scale, eps):
    from serpentine3d.core.geometry import faces_of, volume
    if len(faces_of(shape)) != len(faces_of(rebuilt)):
        raise NotABox("it has faces a box and its fillets do not explain")
    v0, v1 = abs(volume(shape)), abs(volume(rebuilt))
    if abs(v0 - v1) > max(v0, 1.0) * 1e-6 + eps * scale ** 2:
        raise NotABox("rebuilt from its sizes it comes out different")


# --- building ---------------------------------------------------------------

def build(model: BoxModel):
    """The solid: the box, then every fillet at once."""
    from serpentine3d.core.geometry import GeometryError, edges_of, fillet_edges
    u, v, w = (np.asarray(a) for a in model.axes)
    o = np.asarray(model.origin)
    frame = occ.gp_Ax2(occ.gp_Pnt(*map(float, o)), occ.gp_Dir(*map(float, w)),
                       occ.gp_Dir(*map(float, u)))
    box = occ.BRepPrimAPI_MakeBox(frame, *map(float, model.size)).Shape()
    if not model.fillets:
        return box
    picked, radii = [], []
    for edge in edges_of(box):
        key = _edge_key(model, edge)
        if key in model.fillets:
            picked.append(edge)
            radii.append(float(model.fillets[key]))
    if len(picked) != len(model.fillets):
        raise GeometryError("a fillet's edge is not on the box")
    return fillet_edges(box, edges=picked, radii=radii)


def _edge_key(model, edge):
    """Which two faces a straight edge of the box lies on."""
    from OCP.BRepAdaptor import BRepAdaptor_Curve
    curve = BRepAdaptor_Curve(occ.to_edge(edge))
    halfway = (curve.FirstParameter() + curve.LastParameter()) / 2
    mid = _vec(curve.Value(halfway)) - np.asarray(model.origin)
    on = []
    for axis in range(3):
        t = float(np.dot(mid, model.axes[axis])) / model.size[axis]
        if abs(t) < 1e-6:
            on.append((axis, 0))
        elif abs(t - 1) < 1e-6:
            on.append((axis, 1))
    if len(on) != 2:
        return None
    (a, sa), (b, sb) = sorted(on)
    return (a, sa, b, sb)


# --- what a pick means ------------------------------------------------------

@dataclass(frozen=True)
class Pick:
    """What a picked edge or face of the box stands for."""
    what: str               # "size" or "radius"
    axis: int = -1          # for a size: the axis it runs along
    side: int = -1          # for a size picked on a face: the side that moves
    edge: tuple = ()        # for a radius: the box edge it rounds


def pick_of_edge(model: BoxModel, edge) -> Pick:
    from OCP.BRepAdaptor import BRepAdaptor_Curve
    from OCP.GeomAbs import GeomAbs_CurveType
    curve = BRepAdaptor_Curve(edge)
    kind = curve.GetType()
    if kind == GeomAbs_CurveType.GeomAbs_Line:
        d = _vec(curve.Line().Direction())
        for axis in range(3):
            if abs(float(np.dot(d, model.axes[axis]))) > _PARALLEL:
                return Pick("size", axis=axis)
    if kind == GeomAbs_CurveType.GeomAbs_Circle:
        c = curve.Circle()
        key = _edge_of_fillet(model, _vec(c.Axis().Direction()),
                              _vec(c.Location()), float(c.Radius()),
                              max(model.size) * 1e-6)
        if key in model.fillets:
            return Pick("radius", edge=key)
    raise NotABox("that edge is neither a side of the box nor a fillet")


def pick_of_face(model: BoxModel, face) -> Pick:
    kind, data = _surface(face)
    eps = max(model.size) * 1e-6
    if kind == "plane":
        normal, point = data
        for axis in range(3):
            if abs(float(np.dot(normal, model.axes[axis]))) > _PARALLEL:
                t = float(np.dot(point - np.asarray(model.origin),
                                 model.axes[axis]))
                return Pick("size", axis=axis,
                            side=0 if abs(t) <= eps else 1)
    if kind == "cylinder":
        key = _edge_of_fillet(model, *data, eps)
        if key in model.fillets:
            return Pick("radius", edge=key)
    raise NotABox("that face is neither a side of the box nor a fillet")


def axis_name(model: BoxModel, axis: int) -> str:
    """X, Y or Z when the box lines up with the world, else 1st/2nd/3rd."""
    a = np.asarray(model.axes[axis])
    i = int(np.argmax(np.abs(a)))
    if abs(a[i]) > _PARALLEL:
        return "XYZ"[i]
    return ("first", "second", "third")[axis]


def describe(model: BoxModel, fmt=lambda x: f"{x:g}") -> str:
    sides = " x ".join(fmt(s) for s in model.size)
    if not model.fillets:
        return f"box {sides}"
    radii = sorted(set(round(r, 9) for r in model.fillets.values()))
    which = ", ".join(fmt(r) for r in radii)
    return (f"box {sides}, {len(model.fillets)} filleted edge(s) "
            f"of {which}")

import sys

from serpentine3d.core import geometry as g


def serpentine3d_plugin(ctx):
    command = ctx.command

    @command("editdimension")
    def cmd_editdimension(ctx):
        """Show and change a box's size or a fillet's radius from a picked edge.

        Ctrl+Shift-click one edge or face of a box first. A straight edge gives
        the box's length along it, a flat face the distance to the face across
        (that face is the one that moves), a fillet its radius. The box is
        rebuilt and its fillets made again on the same edges, so they keep
        their radius when the box changes size. Works on any box with filleted
        edges, however it was drawn, moved or imported."""
        bd = sys.modules[__name__]
        from serpentine3d.commands.base import NumberReq
        held = list(ctx.selection.subobjects)
        if len(held) != 1:
            ctx.echo("Ctrl+Shift-click one edge or face of a box first: a side "
                     "gives its size, a fillet its radius.")
            return
        obj_id, kind, index = held[0]
        obj = ctx.scene.get(obj_id)
        if obj is None:
            return
        try:
            model = bd.read(obj.shape)
            if kind == "edge":
                pick = bd.pick_of_edge(model, g.edges_of(obj.shape)[index])
            else:
                pick = bd.pick_of_face(model, g.faces_of(obj.shape)[index])
        except bd.NotABox as exc:
            ctx.echo(f"{obj.name} has no dimensions to edit here: {exc}.")
            return
        fmt = ctx.scene.format_length
        ctx.echo(f"{obj.name}: {bd.describe(model, fmt)}.")
        if pick.what == "radius":
            label = "Fillet radius"
            current = model.fillets[pick.edge]
            value = yield NumberReq(f"{label} (0 removes it)", default=current,
                                    minimum=0)
            if value <= 0:
                fillets = dict(model.fillets)
                del fillets[pick.edge]
                new = bd.BoxModel(model.origin, model.axes, model.size, fillets)
            else:
                new = model.with_radius(pick.edge, value)
        else:
            label = f"Size along {bd.axis_name(model, pick.axis)}"
            current = model.size[pick.axis]
            choices = None if pick.side >= 0 else {"Grow": ["Both", "End",
                                                            "Start"]}
            value = yield NumberReq(label, default=current, minimum=0,
                                    choices=choices)
            if value <= 0:
                ctx.echo("A box needs a size above zero.")
                return
            grow = (("start", "end")[pick.side] if pick.side >= 0
                    else ctx.opt("Grow", "Both").lower())
            new = model.resized(pick.axis, value, grow)
        try:
            shape = bd.build(new)
        except g.GeometryError as exc:
            ctx.echo(f"{obj.name}: {exc}. Nothing changed.")
            return
        ctx.scene.replace_shape(obj_id, shape)
        ctx.selection.clear()          # the picked index means another edge now
        ctx.echo(f"{label}: {fmt(current)} → {fmt(value)}.")
